mapper.select:
select id, session_id, role, content, token_count, create_by, create_time
from (
    select id, session_id, role, content, token_count, create_by, create_time
    from lf_chat_message
    where session_id = #{sessionId}
    order by id desc
    limit #{limit}
) t
order by id asc

mapper.insert:
insert into lf_chat_message (
    session_id, role, content, token_count, create_by, create_time
) values (
    #{sessionId}, #{role}, #{content}, #{tokenCount}, #{createBy}, sysdate()
)
